import { IEvent } from './event-interface';
import { DispatchingState } from './event-states/dispatching-state';
import { IEventState } from './event-states/event-state';
import { NonDispatchingState } from './event-states/non-dispatching-state';
import { Listener } from './listener';
import { ListenerNode } from './listener-node';
import { ListenerNodePool } from './listener-node-pool';
import { IStateData } from './state-data';

export abstract class AbstractEvent implements IEvent {
    public state: IEventState;

    protected numberOfListeners: number;

    private stateData: IStateData;

    constructor() {
        this.stateData = {
            listenerNodePool: new ListenerNodePool(),
        };
        this.state = new NonDispatchingState(this, this.stateData);
        this.numberOfListeners = 0;
    }

    public get listenerCount(): number {
        return this.numberOfListeners;
    }

    public get isDispatching(): boolean {
        return this.state instanceof DispatchingState;
    }

    public removeListener(listener: Listener): void {
        const listenerNode: ListenerNode | undefined = this.find(listener);
        if (listenerNode) {
            this.numberOfListeners--;
            this.state.removeListenerNode(listenerNode);
        }
    }

    public removeAllListeners(): void {
        let currentListenerNode: ListenerNode | undefined = this.stateData.head;
        while (currentListenerNode) {
            this.stateData.head = this.stateData.head!.next;
            this.state.removeListenerNode(currentListenerNode);
            currentListenerNode = this.stateData.head;
        }

        this.numberOfListeners = 0;
    }

    public abstract dispatch(...args: any[]): void;

    protected find(listener: Listener): ListenerNode | undefined {
        let currentNode: ListenerNode | undefined = this.stateData.head;
        while (currentNode) {
            if (currentNode.listener === listener) {
                return currentNode;
            }
            currentNode = currentNode.next;
        }
    }

    protected addListenerNode(listener: Listener, context: any, once: boolean): void {
        this.numberOfListeners++;
        const newListenerNode: ListenerNode = this.stateData.listenerNodePool.getNodeFromPool();
        newListenerNode.listener = listener;
        newListenerNode.once = once;
        newListenerNode.context = context;

        this.state.addListenerNode(newListenerNode);
    }
}
